 {singleMenuOpen&&<SinglePlayerMenu close={()=>setSingleMenuOpen(false)} items={()=>{setSingleMenuOpen(false);openHpItems();}} normal={()=>{setSingleMenuOpen(false);setSetupOpen('single');}} rpg={()=>{setSingleMenuOpen(false);openRpgHub();}}/>}
